PBT = r"/bin-types"
R(PBT, "code", "Código do tipo de bin", "Identificador curto e único (ex.: CX-P).", "tag:code")
R(PBT, "name", "Nome do tipo de bin", "Descrição que aparece nas telas.", "tag:name")
R(PBT, "height", "Altura (cm)", "Altura interna útil da bin. Precisa caber no vão do nível, com a folga para tirá-la.", "bin:h")
R(PBT, "width", "Largura (cm)", "Largura da bin: o lado que fica ao longo da frente da estante.", "bin:w")
R(PBT, "length", "Comprimento (cm)", "Comprimento da bin: o lado que vai para o fundo da estante.", "bin:l")
R(PBT, "max_weight", "Peso máximo (kg)", "Peso máximo que a bin suporta.", "bin:weight")
R(PBT, "max_volume", "Volume (litros)", "Volume útil; vazio = calculado pelas medidas.", "bin:vol")
R(PBT, "store_as", "Armazena em", "Unitização: unidades soltas (o arranjo das unidades), caixas do produto (conta caixas inteiras × unidades por caixa), unidades ou caixas (caixas inteiras + o resto solto; a caixa aberta ocupa o espaço de uma caixa) ou palete fechado (caixas por camada × as camadas que cabem na altura e no peso). Produto sem caixa cadastrada fica em unidades.", "bin:h")
R(PBT, "allow_split", "Permitir fracionar a bin pai na otimização", "Só para compartimentos. Com bins existentes (Por endereço e Pool), a bin pai pode virar compartimentos deste tipo (coloca-se a divisória) e os compartimentos de uma mesma bin pai podem voltar a ser a bin pai inteira (tira-se a divisória). A otimização tenta deixar as irmãs na mesma bin pai, sem piorar a caminhada nem a zona de ouro da pega. Desmarcado, nada muda de forma.", "bin:h")
R(PBT, "open_top", "Aberta em cima", "Palete, bandeja ou caixa sem tampa: a carga pode passar da altura da bin. Nas filiais, a altura útil vai até o vão do nível (menos 5 cm para pegar) ou até o máximo acima da borda, o que for menor; no Pool, a menor entre os níveis onde as bins do tipo estão; no projeto de filial nova, até o máximo informado (o nível precisa comportar a bin + esse máximo).", "bin:h")
R(PBT, "over_cm", "Máximo acima da borda (cm)", "Quanto a carga pode subir acima da borda da bin (estabilidade, segurança). Vazio = até o vão do nível. No projeto de filial nova, só vale com o máximo informado.", "bin:h")
R(PBT, "cost", "Custo por bin (R$)", "Usado nos objetivos de menor custo.", "bin:cost")
R(PBT, "parent_id", "Bin pai", "Para frações (compartimentos): a bin inteira que foi dividida.", "bin:parent")
R(PBT, "div_w", "Divisões na largura", "Em quantas partes a bin pai é dividida na largura.", "bin:divw")
R(PBT, "div_l", "Divisões no comprimento", "Em quantas partes a bin pai é dividida no comprimento.", "bin:divl")
R(PBT, "look_model", "Modelo 3D", "Como o tipo aparece no 3D: automático (pelo nome: palete, caixa plástica, gaiola…), desenho simples, um modelo da biblioteca (desenhado com as medidas do cadastro) ou o código colado de uma IA. Só muda o desenho; os cálculos usam as medidas.", "bin:h")
R(PBT, "look_code", "Código da aparência", "O JSON que um chat de IA (Claude, Gemini, ChatGPT…) devolve a partir de uma foto, com o prompt do botão Copiar prompt. Descreve peças simples (caixas e cilindros) em proporção das medidas; o app só lê a descrição, nunca executa código. A prévia mostra o resultado.", "bin:h")
R(PBT, "#lookPromptText", "Prompt para a IA", "O texto que o botão Copiar prompt leva para o chat de IA, já com as medidas do formulário. Aparece aqui quando o navegador não deixa copiar sozinho: selecione e copie.", "bin:h")
R(PBT, "q", "Busca", "Procura pelo código ou nome do tipo de bin.", "find:text")

